-- Phase 8: single-statement history triggers were stored with a trailing ';', which makes mysqldump output
-- unrestorable. Recreate each one with an identical rule in a compound body. No table or data changes.
-- Run in a maintenance window: each guard is absent only between its DROP and CREATE.
DROP TRIGGER `RouteRevision_no_update`;
CREATE TRIGGER `RouteRevision_no_update` BEFORE UPDATE ON `RouteRevision` FOR EACH ROW BEGIN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'IMMUTABLE_HISTORY'; END;
DROP TRIGGER `RouteRevision_no_delete`;
CREATE TRIGGER `RouteRevision_no_delete` BEFORE DELETE ON `RouteRevision` FOR EACH ROW BEGIN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'IMMUTABLE_HISTORY'; END;
DROP TRIGGER `RouteStop_no_update`;
CREATE TRIGGER `RouteStop_no_update` BEFORE UPDATE ON `RouteStop` FOR EACH ROW BEGIN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'IMMUTABLE_HISTORY'; END;
