CREATE TRIGGER `RouteStop_no_delete` BEFORE DELETE ON `RouteStop` FOR EACH ROW BEGIN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'IMMUTABLE_HISTORY'; END;
